package com.example.editor.remote.auth.provider;

import java.net.URI;
import java.util.List;
import com.example.editor.remote.auth.RemoteAuthException;
import com.example.editor.remote.auth.RemoteAuthProperties;
import com.example.editor.remote.auth.RemoteCredentialMaterial;
import com.example.editor.remote.storage.RemoteStorageProperties;
import com.example.editor.remote.storage.RemoteStorageProviderType;

/** SPI OAuth independiente del módulo de usuarios y de la SPI de almacenamiento. */
public interface RemoteOAuthProvider {
    /** Descripción: Ejecuta la operación «type» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ RemoteStorageProviderType type();
    /** Descripción: Ejecuta la operación «scopes» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ List<String> scopes(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile);
    /** Descripción: Ejecuta la operación «authorizationUri» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse; redirectUri: dato de entrada necesario para la operación; state: dato de entrada necesario para la operación; challenge: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ URI authorizationUri(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile,String redirectUri,String state,String challenge,List<String> scopes);
    /** Descripción: Ejecuta la operación «exchange» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse; redirectUri: dato de entrada necesario para la operación; code: dato de entrada necesario para la operación; verifier: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ RemoteCredentialMaterial exchange(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile,String redirectUri,String code,String verifier,List<String> scopes);
    /** Descripción: Ejecuta la operación «refresh» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse; current: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ RemoteCredentialMaterial refresh(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile,RemoteCredentialMaterial current);
    /** Descripción: Ejecuta la operación «revoke» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse; current: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ void revoke(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile,RemoteCredentialMaterial current);
    /** Descripción: Ejecuta la operación «useDeviceFlow» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse. Salida: devuelve un indicador que expresa el resultado de la condición. */ default boolean useDeviceFlow(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile){return false;}
    /** Descripción: Ejecuta la operación «beginDeviceAuthorization» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ default RemoteDeviceAuthorization beginDeviceAuthorization(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile,List<String> scopes){throw unsupported();}
    /** Descripción: Ejecuta la operación «pollDeviceAuthorization» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: storageProfile: archivo o contenido que debe procesarse; authProfile: archivo o contenido que debe procesarse; deviceCode: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ default RemoteDevicePollResult pollDeviceAuthorization(RemoteStorageProperties.Profile storageProfile,RemoteAuthProperties.Provider authProfile,String deviceCode,List<String> scopes){throw unsupported();}
    /** Descripción: Ejecuta la operación «unsupported» correspondiente a la responsabilidad de RemoteOAuthProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private RemoteAuthException unsupported(){return new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"The selected OAuth provider does not support device authorization");}
}
